BEGIN;
CREATE TABLE IF NOT EXISTS public.app_settings(id text PRIMARY KEY,value text NOT NULL,revision integer NOT NULL DEFAULT 1,updated text NOT NULL);
CREATE TABLE IF NOT EXISTS public.accounts(id text PRIMARY KEY,role text NOT NULL,name text NOT NULL,code_hash text NOT NULL,active integer NOT NULL DEFAULT 1,version integer NOT NULL DEFAULT 1,password_hash text NOT NULL DEFAULT '',permissions text NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS public.login_attempts(key text PRIMARY KEY,count integer NOT NULL,expires bigint NOT NULL);
CREATE TABLE IF NOT EXISTS public.requests(seq integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id text NOT NULL UNIQUE,site_id text NOT NULL,state text NOT NULL,created text NOT NULL,updated text NOT NULL,data text NOT NULL,revision integer NOT NULL DEFAULT 1,received_value double precision NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.suppliers(id text PRIMARY KEY,name text NOT NULL,phone text NOT NULL,email text NOT NULL,notes text NOT NULL,active integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS public.sync_status(id text PRIMARY KEY,last_success text NOT NULL DEFAULT '',last_error text NOT NULL DEFAULT '',line_count integer NOT NULL DEFAULT 0,last_attempt text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS public.supplier_invoices(id text PRIMARY KEY,request_id text NOT NULL,supplier_id text NOT NULL,number text NOT NULL,date text NOT NULL,due text NOT NULL DEFAULT '',total_cents integer NOT NULL,notes text NOT NULL DEFAULT '',created text NOT NULL,"by" text NOT NULL);
CREATE TABLE IF NOT EXISTS public.invoice_payments(id text PRIMARY KEY,invoice_id text NOT NULL,amount_cents integer NOT NULL,date text NOT NULL,method text NOT NULL,reference text NOT NULL DEFAULT '',created text NOT NULL,"by" text NOT NULL);
CREATE TABLE IF NOT EXISTS public.stock_moves(id text PRIMARY KEY,site_id text NOT NULL,item_key text NOT NULL,name text NOT NULL,spec text NOT NULL DEFAULT '',unit text NOT NULL,qty double precision NOT NULL,kind text NOT NULL,date text NOT NULL,note text NOT NULL,created text NOT NULL,"by" text NOT NULL);
CREATE TABLE IF NOT EXISTS public.invoice_files(id text PRIMARY KEY,request_id text NOT NULL,uploader text NOT NULL,filename text NOT NULL,mime text NOT NULL,size integer NOT NULL,blob_key text NOT NULL UNIQUE,created text NOT NULL,invoice_id text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS requests_site_idx ON public.requests(site_id);
CREATE INDEX IF NOT EXISTS invoice_files_invoice_idx ON public.invoice_files(invoice_id);
CREATE INDEX IF NOT EXISTS invoice_payments_invoice_idx ON public.invoice_payments(invoice_id);
CREATE INDEX IF NOT EXISTS stock_moves_site_idx ON public.stock_moves(site_id);
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.login_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.sync_status ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.supplier_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_payments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stock_moves ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_files ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.app_settings,public.accounts,public.login_attempts,public.requests,public.suppliers,public.sync_status,public.supplier_invoices,public.invoice_payments,public.stock_moves,public.invoice_files FROM anon,authenticated;
COMMIT;
